"use client";

// Curvas de nivel de verdad — un campo de elevación construido a partir de
// crestas alargadas de verdad (varias, con distinto tamaño/ángulo/altura,
// como picos y espolones reales, no ruido isotrópico tipo mancha) del que
// se extraen las líneas de contorno con marching squares y se suavizan por
// recorte de esquinas (Chaikin) + spline, el mismo tipo de proceso que usa
// cualquier software SIG/topográfico real. 45 líneas en 13 niveles —
// anillos anidados alrededor de cada cresta, más juntos en las pendientes
// pronunciadas, más separados en los valles: así se lee como relieve real
// y no como un patrón decorativo aleatorio. Fondo fijo de toda la web;
// deriva muy despacio para que "se muevan un poco" sin que el patrón
// entero parezca desplazarse de un lado a otro.
import { motion } from "framer-motion";

